`toEmbedUrl` host validation is excellently covered. Gaps are elsewhere in the same file:

- **`addCommands().setFigmaEmbed`** — zero test coverage of the TipTap command itself.
- **`renderHTML`** iframe attributes (`sandbox`, `allowfullscreen`) not asserted — only that a `div` is rendered (per the truncated test).
- **`parseHTML`** doesn't verify `src` is actually recovered from the parsed DOM node (the existing test admits this: "the actual extraction happens in parseHTML rules").

```ts
describe("FigmaEmbed.renderHTML iframe safety attributes", () => {
  test("iframe carries sandbox=allow-same-origin (never allow-scripts)", () => {
    const output = FigmaEmbed.config.renderHTML({
      HTMLAttributes: { src: "https://www.figma.com/file/abc/Design" },
    });
    const iframe = (output as unknown[]).find(
      (n) => Array.isArray(n) && n[0] === "iframe",
    ) as [string, Record<string, string>];
    expect(iframe[1].sandbox).toBe("allow-same-origin");
  });
});

describe("FigmaEmbed.addCommands setFigmaEmbed", () => {
  test("inserts a figmaEmbed node with the given src", () => {
    const insertContent = mock((c: unknown) => true) as (c: unknown) => boolean;
    const cmd = (FigmaEmbed.config.addCommands as () => Record<string, unknown>)
      .call(FigmaEmbed)["setFigmaEmbed"] as (attrs: { src: string }) => (ctx: unknown) => boolean;
    const result = cmd({ src: "https://figma.com/file/x" })({ commands: { insertContent } });
    expect(result).toBe(true);
    expect(insertContent).toHaveBeenCalledWith(
      expect.objectContaining({ type: "figmaEmbed", attrs: { src: "https://figma.com/file/x" } }),
    );
  });
});
```

