- **`sourceCaps`** has exactly one test case. Missing: already-uppercase input, empty string, strings with punctuation/spaces.
- **`withTimeout`** — visible test only covers the resolve-before-deadline path; the rejection-on-timeout path and timer cleanup (`clearTimeout` firing on early resolve, so no dangling handle) aren't shown as tested.

```ts
describe("sourceCaps additional cases", () => {
  test("leaves an already-uppercase source unchanged", () => {
    expect(sourceCaps("INTERCOM")).toBe("INTERCOM");
  });
  test("handles an empty string", () => {
    expect(sourceCaps("")).toBe("");
  });
  test("upcases mixed-case with punctuation", () => {
    expect(sourceCaps("zen-desk")).toBe("ZEN-DESK");
  });
});

describe("withTimeout timeout path", () => {
  test("rejects with a friendly message when the promise never settles before the deadline", async () => {
    const neverSettles = new Promise<string>(() => {});
    await expect(withTimeout(neverSettles, 20)).rejects.toThrow(
      "The server took too long to answer. Retry in a moment.",
    );
  });

  test("clears the timer on early resolve (no leaked timer keeps the process alive)", async () => {
    const clearSpy = spyOn(global, "clearTimeout");
    await withTimeout(Promise.resolve("ok"), 1000);
    expect(clearSpy).toHaveBeenCalled();
    clearSpy.mockRestore();
  });
});
```

