- **`usePrefersReducedMotion`** — a React hook, exported, with zero visible test coverage (needs `@testing-library/react`'s `renderHook` or equivalent, plus mocking `matchMedia` and the `data-motion` dataset attribute).
- **`resolveKindColors`** truncated test covers the "window defined" and "window undefined" happy paths, but not the case where `getComputedStyle` returns an **empty string** for a token (should fall back to the literal `fallback`, per the `resolved || v.fallback` logic) — that's the actual bug-prone branch.

```ts
import { renderHook, act } from "@testing-library/react";

describe("usePrefersReducedMotion", () => {
  test("reflects the OS media query", () => {
    const listeners: Array<() => void> = [];
    globalThis.window.matchMedia = ((query: string) => ({
      matches: true,
      media: query,
      addEventListener: (_: string, cb: () => void) => listeners.push(cb),
      removeEventListener: () => {},
    })) as never;
    const { result } = renderHook(() => usePrefersReducedMotion());
    expect(result.current).toBe(true);
  });

  test("reflects the in-product data-motion=off toggle even when the OS query is false", () => {
    document.documentElement.dataset.motion = "off";
    globalThis.window.matchMedia = ((query: string) => ({
      matches: false, media: query, addEventListener: () => {}, removeEventListener: () => {},
    })) as never;
    const { result } = renderHook(() => usePrefersReducedMotion());
    expect(result.current).toBe(true);
    delete document.documentElement.dataset.motion;
  });
});

describe("resolveKindColors empty-token fallback", () => {
  test("falls back to the literal fallback color when getPropertyValue returns empty", () => {
    Object.defineProperty(globalThis, "window", {
      value: { getComputedStyle: () => ({ getPropertyValue: () => "" }) },
      writable: true,
    });
    const result = resolveKindColors({} as HTMLElement);
    expect(result.get("signal")).toBe("#e5bddf"); // KIND_VISUAL.signal.fallback
  });
});
```

