The visible portion tests `runStatusLabel`, `hasCanvasContent`, `ProgressBlock`, `MemoryBlock` — but **`CriticBlock`** (imported at the top) has no visible test at all, despite being one of three canvas blocks and part of `hasCanvasContent`'s contract.

```ts
describe("CriticBlock", () => {
  it("returns null when there is no critic verdict", () => {
    expect(CriticBlock({ verdict: null })).toBeNull();
  });

  it("renders the verdict word and confidence when a verdict is present", () => {
    const verdict: CriticReview = {
      verdict: "ship", summary: "clear win", risks: [], kill_criteria: [],
      missing_evidence: [], confidence: 0.8, reviewer_model: "test",
      reviewed_at: "2026-07-03T00:00:00Z",
    };
    const result = CriticBlock({ verdict });
    expect(result?.type).toBe("div");
  });

  it("surfaces risks and kill_criteria when present, without crashing on empty arrays", () => {
    const verdict: CriticReview = {
      verdict: "revise", summary: "", risks: ["scope creep"], kill_criteria: ["no signal in 2wk"],
      missing_evidence: [], confidence: 0.4, reviewer_model: "test",
      reviewed_at: "2026-07-03T00:00:00Z",
    };
    expect(CriticBlock({ verdict })).not.toBeNull();
  });
});
```

